                        assert(self.perms@.index((j-1) as nat) == old(self).perms@.index((j-1) as nat));
                        assert(self.perms@.index((j - 1) as nat)
                            == old(self).perms@.index((j - 1) as nat));
                    }
                    assert(perm.value().ptr.addr() == next_ptr.addr());
                } else {
                    assert(perm.value().ptr.addr() == next_ptr.addr());
                }

